edits.old:
if hasattr(args, "posonlyargs"):
    for arg in args.posonlyargs:  # type: ignore
        annotation = ast_unparse(arg.annotation) or Parameter.empty
        params.append(Parameter(arg.arg, Parameter.POSITIONAL_ONLY,
                                annotation=annotation))

for i, arg in enumerate(args.args):
    if len(args.args) - i <= len(args.defaults):
        default = ast_unparse(args.defaults[-len(args.args) + i])
    else:
        default = Parameter.empty

    annotation = ast_unparse(arg.annotation) or Parameter.empty
    params.append(Parameter(arg.arg, Parameter.POSITIONAL_OR_KEYWORD,
                            default=default, annotation=annotation))

edits.new:
positional_only = getattr(args, "posonlyargs", [])
positional = positional_only + args.args
first_default = len(positional) - len(args.defaults)
for i, arg in enumerate(positional):
    if i >= first_default:
        default = ast_unparse(args.defaults[i - first_default])
    else:
        default = Parameter.empty

    kind = (Parameter.POSITIONAL_ONLY if i < len(positional_only)
            else Parameter.POSITIONAL_OR_KEYWORD)
    annotation = ast_unparse(arg.annotation) or Parameter.empty
    params.append(Parameter(arg.arg, kind, default=default,
                            annotation=annotation))
